DO $$ BEGIN CREATE TYPE funding_status AS ENUM ('quoted','pending','completed','released','failed','expired'); EXCEPTION WHEN duplicate_object THEN null; END $$;
CREATE TABLE IF NOT EXISTS funding_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),provider text NOT NULL,provider_order_id text UNIQUE,external_reference text UNIQUE NOT NULL,currency text NOT NULL,amount_local numeric(18,2),fee_local numeric(18,2),amount_usdc numeric(18,6) NOT NULL,rate numeric(24,10),destination_address text NOT NULL,release_chain text NOT NULL DEFAULT 'base',status funding_status NOT NULL DEFAULT 'quoted',receipt_number text,release_tx_hash text,failure_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS funding_orders_user_idx ON funding_orders(user_id);